package com.example.demo.controller;
import com.example.demo.dto.RegisterRequest;import com.example.demo.service.UserService;import jakarta.validation.Valid;import org.springframework.stereotype.Controller;import org.springframework.ui.Model;import org.springframework.validation.BindingResult;import org.springframework.web.bind.annotation.*;import org.springframework.web.servlet.mvc.support.RedirectAttributes;
@Controller public class AuthController {private final UserService users;public AuthController(UserService u){users=u;}@GetMapping("/register")String form(Model m){if(!m.containsAttribute("request"))m.addAttribute("request",new RegisterRequest("","","","","","",""));return "auth/register";}@PostMapping("/register")String register(@Valid @ModelAttribute("request") RegisterRequest r, BindingResult br,Model m, RedirectAttributes ra){if(!r.password().equals(r.passwordConfirmation()))br.rejectValue("passwordConfirmation","mismatch","Пароли не совпадают");if(br.hasErrors())return "auth/register";try{users.register(r);}catch(IllegalArgumentException e){m.addAttribute("error",e.getMessage());return "auth/register";}ra.addFlashAttribute("success","Регистрация завершена. Войдите в систему.");return "redirect:/login";}}
